import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Descargas y actualizaciones","description":"","frontmatter":{"title":"Descargas y actualizaciones","docId":"user.start.updates","translationKey":"user.start.updates","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6b92351b3ee8eb1b0745db65bbddb3eab21f4ae0a9945795c94147c9ca347e73","translationRevision":"98a7c2cfe052496880550d587bd75ee988e03d0ac01aa3ac71d3c769b7b0814e","order":40},"headers":[],"relativePath":"es/user/updates.md","filePath":"es/user/updates.md","lastUpdated":1795727787000}`),a={name:`es/user/updates.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="downloads-and-updates" tabindex="-1">Descargas y actualizaciones <a class="header-anchor" href="#downloads-and-updates" aria-label="Permalink to “Descargas y actualizaciones”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Elegir el canal correcto y actualizar sin confundir la búsqueda de versiones con una instalación automática. Cierra las sesiones activas y respalda los datos locales antes de cambiar de versión, especialmente si sus notas documentan una migración de base de datos.</p><h2 id="select-a-channel" tabindex="-1">Elige un canal <a class="header-anchor" href="#select-a-channel" aria-label="Permalink to “Elige un canal”">​</a></h2><p>La <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versiones</a> distingue versiones estables y preliminares. Un candidato como <code>-rc</code> sirve para verificación. El actualizador distingue los feeds estable y beta y autentica sus metadatos firmados antes de ofrecer una versión. Un JSON sin firma o un instalador modificado no constituye una actualización válida.</p><h2 id="check-and-install" tabindex="-1">Buscar e instalar <a class="header-anchor" href="#check-and-install" aria-label="Permalink to “Buscar e instalar”">​</a></h2><ol><li>Abre <strong>Settings → General</strong> y comprueba la versión instalada y el estado del actualizador.</li><li>Ejecuta la comprobación disponible. Si la compilación no configura la clave pública o el feed, mostrará que esa capacidad no está disponible.</li><li>Lee las notas y elige el paquete de tu plataforma.</li><li>Sigue la descarga o instalación manual que ofrezca tu compilación. El workflow habilita comprobaciones autenticadas solo si está configurada la variable de clave pública; la instalación automática tiene puertas adicionales.</li><li>Para actualizar manualmente, cierra TikTools, instala o sustituye el paquete completo verificado y vuelve a abrirlo. Conserva los datos fuera de los archivos de la aplicación.</li></ol><h2 id="expected-result" tabindex="-1">Resultado esperado <a class="header-anchor" href="#expected-result" aria-label="Permalink to “Resultado esperado”">​</a></h2><p>La aplicación reiniciada informa de la versión elegida y abre el perfil local esperado. Los ZIP/TAR portátiles requieren sustitución manual. Un ejecutable extraído o una instalación no reconocida también puede requerir ese procedimiento aunque exista un instalador AppImage.</p><h2 id="recovery-and-limitations" tabindex="-1">Recuperación y límites <a class="header-anchor" href="#recovery-and-limitations" aria-label="Permalink to “Recuperación y límites”">​</a></h2><p>Una firma inválida significa que la actualización falló: descarga una copia oficial nueva y verifica sus checksums. No omitas la verificación. El reemplazo automático de AppImage y la entrega a NSIS tienen gates de compilación separados y son experimentales. No existe un rollback automático general. Volver a un binario anterior no deshace una migración SQLite.</p><p>Reporta la versión, el formato del paquete y el error del actualizador desde Diagnostics. No adjuntes claves de firma, tokens de invitación ni datos de cuenta. La <a href="./installation.html">guía de instalación</a> describe los formatos compatibles.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalles de operación”">​</a></h2><p>La capacidad del updater se fija al compilar. Comprobar requiere feed y clave pública. AppImage automático exige además puerta común de instalación y origen compatible detectado; NSIS exige esa misma puerta Y la específica NSIS. Variables de entorno después de instalar no habilitan puertas compiladas. Portable/extraído/desconocido usa reemplazo manual. Verifica versión, reinicio y perfil tras instalar; descarga, checksum o lanzar instalador no prueban finalización.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};